const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { stages: [], total_entry: 0, total_converted: 0, overall_rate: 0 } }];

const stages = rows.map((row, idx) => {
  const visitors = parseInt(row['Visitors'] || 0);
  const next = rows[idx + 1] ? parseInt(rows[idx + 1]['Visitors'] || 0) : null;
  const dropoff = next !== null ? visitors - next : 0;
  const dropoff_rate = visitors > 0 && next !== null ? ((dropoff / visitors) * 100).toFixed(1) : null;
  return {
    stage: row['Stage'],
    visitors,
    dropoff,
    dropoff_rate: dropoff_rate ? parseFloat(dropoff_rate) : null,
    is_biggest_dropoff: false
  };
});

const withRates = stages.filter(s => s.dropoff_rate !== null);
if (withRates.length) {
  const maxDropoff = Math.max(...withRates.map(s => s.dropoff_rate));
  stages.forEach(s => { if (s.dropoff_rate === maxDropoff) s.is_biggest_dropoff = true; });
}

const first = stages[0]?.visitors || 0;
const last = stages[stages.length - 1]?.visitors || 0;
const overall = first > 0 ? ((last / first) * 100).toFixed(1) : 0;

return [{ json: { stages, total_entry: first, total_converted: last, overall_conversion_rate: parseFloat(overall) } }];

const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const diagnosis = JSON.parse(raw);
return [{ json: { ...diagnosis, funnel: $('Calculate Drop-off Rates').item.json } }];

